from PIL import Image, ImageDraw
im = Image.open('radiograph.jpg').convert('RGB')
for name,box in [('c_ur',(600,340,1050,720)),('c_ul',(1600,340,2000,720)),('c_lr',(600,620,1050,1000)),('c_ll',(1600,620,2000,1000))]:
    c=im.crop(box); W=box[2]-box[0]; H=box[3]-box[1]
    d=ImageDraw.Draw(c)
    for x in range(0,W,25):
        col=(255,0,0) if x%100==0 else (255,150,150)
        d.line([(x,0),(x,H)],fill=col,width=1)
        if x%50==0: d.text((x+1,1),str(round((box[0]+x)/2473,2)),fill=(255,0,0))
    for y in range(0,H,25):
        col=(0,180,255) if y%100==0 else (150,220,255)
        d.line([(0,y),(W,y)],fill=col,width=1)
        if y%50==0: d.text((1,y+1),str(round((box[1]+y)/1252,2)),fill=(0,120,255))
    c.resize((W*3,H*3)).save(name+'.png')
print('ok')
"", "description": "High-zoom coordinate crops of four candidate regions"}

