from PIL import Image, ImageDraw
im=Image.open('radiograph.jpg').convert('RGB')
def crop(name,box,sc=5):
    c=im.crop(box); W=box[2]-box[0]; H=box[3]-box[1]
    d=ImageDraw.Draw(c)
    for x in range(0,W,25):
        d.line([(x,0),(x,H)],fill=(255,0,0) if x%100==0 else (255,180,180),width=1)
        if x%50==0: d.text((x+1,1),str(round((box[0]+x)/2473,2)),fill=(255,0,0))
    for y in range(0,H,25):
        d.line([(0,y),(W,y)],fill=(0,120,255) if y%100==0 else (180,225,255),width=1)
        if y%50==0: d.text((1,y+1),str(round((box[1]+y)/1252,2)),fill=(0,90,255))
    c.resize((W*sc,H*sc)).save(name+'.png')
crop('b1',(690,430,900,640))
crop('b2',(1780,430,2000,620))
crop('b3',(690,690,930,880))
crop('b4',(1500,720,1720,930))
print('ok')
